// @ts-nocheck
"use client";

import {getUserReviews} from "@/services/reviewTour";
import {getCookie} from "cookies-next";
import React, {useEffect, useState} from "react";
import Breadcrumb from "@/components/header/breadcrumb";
import Menu from "@/components/profile-page/menu";
import Rating from "react-rating";
import formatDate from "@/helpers/FormatDate";
import {FontAwesomeIcon} from "@fortawesome/react-fontawesome";
import {faStar as faRegularStar} from "@fortawesome/free-regular-svg-icons";
import {faStar, faArrowUpRightFromSquare, faPenToSquare} from "@fortawesome/free-solid-svg-icons";
import Ratings from "@/components/tour-detail-page/rating";

export default function Reviews() {
    const [reviews, setReviews] = useState([])
    const [loading, setLoading] = useState(false);
    const [errorMessage, setErrorMessage] = useState("");
    const [updatableReview, setUpdatableReview] = useState(null)
    const [reviewModalOpen, setReviewModalOpen] = useState(false)

  const fetchReviews = async () => {
    setLoading(true);
    await getUserReviews({token : getCookie('auth-token-v3') ?? ""}).then((res) => {
       if (res.success){
           setReviews(res.data);
       }
       else {
           setErrorMessage("Could not fetch data")
       }
       setLoading(false);
    });
  };

  useEffect(() => {
    fetchReviews();
  }, []);

  return (
      <main className="tw-font-display">
          <div className="tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6">

              <Breadcrumb items={[{pageTitle: "Profile", pageUrl: "/profile"}]}/>
              <h1 className="tw-mt-2 tw-mb-5 tw-text-[clamp(22px,2.6vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
                  My Tour Reviews
              </h1>

              <div className="tw-grid tw-grid-cols-1 tw-gap-6 md:tw-grid-cols-[260px_minmax(0,1fr)]">
                  <div>
                      <Menu/>
                  </div>

                  <div>
                      {loading && (
                          <div className="tw-flex tw-flex-col tw-items-center tw-gap-3 tw-py-16 tw-text-[#5d556c]">
                              <span className="tw-inline-block tw-h-8 tw-w-8 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent" />
                              <p className="tw-m-0 tw-text-sm">Loading. Please wait.</p>
                          </div>
                      )}

                      {errorMessage && (
                          <div className="tw-mb-4 tw-rounded-xl tw-border tw-border-solid tw-border-[#f3c2c2] tw-bg-[#fdecec] tw-px-4 tw-py-3 tw-text-sm tw-text-[#b23838]">
                              {errorMessage}
                          </div>
                      )}

                      <div className="tw-grid tw-grid-cols-1 tw-gap-5 sm:tw-grid-cols-2 lg:tw-grid-cols-3">
                          {reviews.map((review, index) =>
                              <ReviewItem
                                  review={review}
                                  key={index}
                                  setUpdatableReview={setUpdatableReview}
                                  onEdit={() => setReviewModalOpen(true)}
                              />
                          )}

                          {!loading && reviews.length === 0 &&
                              <div className="tw-col-span-full tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-py-12 tw-text-center tw-text-sm tw-text-[#6b6577]">
                                  You did not make any review yet.
                              </div>
                          }
                      </div>
                  </div>
              </div>
          </div>


          {/*review update modal*/}
          <Ratings
              modalOnly={true}
              updatableReview={updatableReview}
              tourID={null}
              open={reviewModalOpen}
              onClose={() => setReviewModalOpen(false)}
          />

      </main>
  );
}

export function ReviewItem({review, setUpdatableReview, onEdit}: { review: any, setUpdatableReview: any, onEdit?: () => void }) {

    return (
        <div className="tw-group tw-flex tw-flex-col tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-transition-all tw-duration-300 hover:tw--translate-y-1 hover:tw-shadow-[0_14px_34px_rgba(20,16,28,0.12)]">
            <div className="tw-relative tw-overflow-hidden tw-rounded-t-2xl tw-transform-gpu">
                <div className="tw-aspect-[16/10]">
                    <img
                        src={review.tour.image}
                        className="tw-h-full tw-w-full tw-object-cover tw-transition-transform tw-duration-500 group-hover:tw-scale-105"
                        alt={review.tour.name}
                    />
                </div>
            </div>

            <div className="tw-flex tw-flex-1 tw-flex-col tw-p-4">
                <h2 className="tw-m-0 tw-text-base tw-font-bold tw-text-[#14101c] group-hover:tw-text-[#854ec9]">
                    {review.tour.name}
                </h2>

                <div className="tw-my-3 tw-flex tw-items-center tw-gap-3 tw-border-0 tw-border-y tw-border-solid tw-border-[#f0edf5] tw-py-3">
                    <img
                        src={
                            (getCookie('user-avatar') && getCookie('user-avatar') != 'null') ?
                                getCookie('user-avatar') :
                                "/images/no-profile.png"
                        }
                        className="tw-h-9 tw-w-9 tw-rounded-full tw-object-cover"
                        alt="profile"
                    />
                    <div className="tw-leading-tight">
                        <div className="tw-text-sm tw-font-semibold tw-text-[#14101c]">{getCookie('user-full-name')}</div>
                        <small className="tw-text-xs tw-text-[#6b6577]">
                            Posted on {formatDate(new Date(review.created_at))}
                        </small>
                    </div>
                </div>

                <div className="tw-flex tw-items-center tw-gap-2 tw-text-sm tw-text-[#6b6577]">
                    <Rating
                        emptySymbol={
                            <FontAwesomeIcon icon={faRegularStar} className="tw-text-[#c9c4d4]" size={"lg"}/>
                        }
                        fullSymbol={
                            <FontAwesomeIcon icon={faStar} className="tw-text-[#f5a623]" size={"lg"}/>
                        }
                        initialRating={review.rating ?? 5}
                        readonly={true}
                    />
                    <span className="tw-font-semibold tw-text-[#14101c]">({review.rating ?? 5})</span>
                </div>

                <p className="tw-mt-2 tw-mb-0 tw-flex-1 tw-text-sm tw-leading-relaxed tw-text-[#5d556c] tw-text-justify">
                    {review.comment.length > 200 ? review.comment.slice(0, 195) + "..." : review.comment}
                </p>

                <div className="tw-mt-4 tw-flex tw-items-center tw-justify-between tw-border-0 tw-border-t tw-border-solid tw-border-[#f0edf5] tw-pt-3">
                    <a
                        target={"_blank"}
                        href={"/tour/" + review.tour.slug}
                        className="tw-flex tw-items-center tw-gap-1.5 tw-text-sm tw-font-semibold tw-text-[#854ec9] tw-no-underline hover:tw-text-[#6a3da4]"
                    >
                        <FontAwesomeIcon icon={faArrowUpRightFromSquare} className="tw-text-xs"/>
                        Open tour page
                    </a>

                    <button
                        type="button"
                        onClick={() => {
                            setUpdatableReview({
                                id: review.id,
                                rating: review.rating,
                                comment: review.comment,
                            });
                            onEdit?.();
                        }}
                        className="tw-flex tw-items-center tw-gap-1.5 tw-border-0 tw-bg-transparent tw-text-sm tw-font-semibold tw-text-[#5d556c] tw-no-underline tw-cursor-pointer hover:tw-text-[#14101c]"
                    >
                        <FontAwesomeIcon icon={faPenToSquare} className="tw-text-xs"/>
                        Edit review
                    </button>
                </div>
            </div>
        </div>
    )
}
